from taf.transport.ssh.connection import SSHConnection
from SSHLibrary.pythonclient import SFTPClient


class SSHAdapter(SSHConnection):
    """
    This class aims to adapt SSHConnection from taf.transport.ssh,
    so that it can be used in ute_wtssim.
    """
    def __init__(self, settings):
        """ Configure and issue a connection using given ConnectionSettings.
        """
        super(SSHAdapter, self).__init__()
        config = {
            "hostname": settings.host_ip,
            "username": settings.ssh_username,
            "password": settings.ssh_password,
            "port": settings.ssh_port
        }
        self.configure(**config)
        self.connect()
        self.sftp_client = SFTPClient(self._client, 'utf-8')

    def execute_command(self, command):
        """ Send command to the remote host, return output files and exit code.

        Sending a command via this method will make the process stay up after
        collecting this instance.
        """
        self.send_command(command)
        out = self.read_output()
        err = self.read_error()
        rc = self.exit_code
        return out, err, rc

    def get_file(self, source, destination='.'):
        """ Same as in ute_wtssim.

        Since ute_wtssim uses unicode() inside of SFTPClient, this will not
        work in python3.
        """
        return self.sftp_client.get_file(source, destination, '/')

    def close(self):
        self.sftp_client = None
        self.disconnect()
